def semver_sort(versions):
    def parse_key(v):
        # strip build metadata
        core = v.split('+', 1)[0]
        if '-' in core:
            main, pre = core.split('-', 1)
        else:
            main, pre = core, None

        major, minor, patch = (int(x) for x in main.split('.'))

        if pre is None:
            pre_flag = 1  # no prerelease sorts after
            pre_key = ()
        else:
            pre_flag = 0
            ids = pre.split('.')
            pre_key = tuple(
                (0, int(i)) if i.isdigit() else (1, i)
                for i in ids
            )

        return (major, minor, patch, pre_flag, pre_key)

    return sorted(versions, key=parse_key)

